   [59]={next_id=60, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="星火人自有一套语言系统，按照你先前了解到的信息，她口中的“妖气”正是虚粒子风暴在星火的称呼，你不禁有些在意这件事。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [60]={next_id=61, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="莫非你知道那件事？", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [61]={next_id=62, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="鸣晔也有些诧异。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我记得那日先是从天际传来一股类似爆炸的巨响，随后是巨大的妖气冲击……", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她蹙眉思考，认真回忆着自己先前曾见过的景象。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那时西边的妖气以一种涡旋的方式向这里的天空汇集，连师父都说，可能有大妖出世。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="涡旋状的虚粒子风暴……大妖……难道说……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从时间和地址判断，鸣晔口中那件事正是当初斯科皮欧降临时引发的动静，它所带来的锚点空间引发了一次大规模的虚粒子风暴，只是它的后续影响竟然牵涉到了星火那边，这叫你有些诧异。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你可是想起来什么？", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大概可以和你说的对上，你所说的大妖名为斯科皮欧，按照莱斯坦斯的称呼，它是一名高阶修格尔，在它降临不久就被我们合力击溃了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如此……那我便安心了。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="鸣晔眉头舒展，唇角微微翘起露出笑意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我当时还向师父请求出战，师父却叫我稍安勿躁，说是这边自有人会击溃它，不曾想竟然是你。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我当时循着宝樽消失的方向一路寻找，因为路上帮着安置了一些受灾的民众，错过了寻回它的最好时机。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="幸亏宝樽是我家传下来的宝物，即使落在了旁人的手中，也无法彻底切断它与我的联系，凭着冥冥中的联系我四处寻找，几经周折，我终于确认了它的所在。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她说着看向天空，你也抬头看了过去，微风吹拂，竟然在半空中卷起一道细小的虚粒子风暴。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="鸣晔抬起手，紫金色的电光从她指尖飞出，感知到了星源共鸣的力量，莫比乌斯环也开始产生反应。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这就是我没能想到的地方，此时宝樽已被妖气污染，我无暇再考虑其他，匆忙回到洞天里，试图净化妖气并夺回宝樽的控制权。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她眉眼间有股淡淡的惆怅，你看着她的神情，本能地觉得这中间一定还发生了别的事情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="然后呢？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="九成以上妖气都被我净化完全，只有最后一缕，无论如何都无法彻底消除。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这最后一缕妖气有些特殊。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="它与宗门圣地深处所潜藏的气息有所接近，我也试着潜入洞天深处与外层寻找，始终没能找到源头，仿佛是凭空出现，本不该属于这里一样。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [82]={next_id=83, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="中间偶尔也有一些人会受到外泄的妖气影响被卷入洞天，不过她们基本都被我在第一时间送出去了。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [83]={next_id=84, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她说这句话的时候紧紧盯着你，眼中稍有疑惑和不解，甚至还带着几分期待。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [84]={next_id=85, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="只有你，当我在庭院的花枝间发现你时，发现那股特殊的妖气受到你的吸引，在你的周身逐渐汇集。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530", 0, 0, 62, 185.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
